css:
.sl-feature-hub {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-feature-hub h2 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-feature-hub .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-feature-hub .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-feature-hub .sl-bg-card {
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
}
.sl-feature-hub .sl-border { border-color: var(--smartlearn-card-border); }
.sl-feature-hub .sl-hub-subtitle { max-width: 600px; }
.sl-feature-hub .sl-media-fallback {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text-muted);
}
.sl-feature-hub .sl-node-avatar {
    width: 32px;
    height: 32px;
    flex-shrink: 0;
}
.sl-feature-hub .sl-node-pill {
    transition: scale 0.3s ease, border-color 0.3s ease;
    white-space: nowrap;
}
.sl-feature-hub .sl-node:hover .sl-node-pill,
.sl-feature-hub .sl-node:focus-within .sl-node-pill {
    scale: 1.08;
    border-color: var(--smartlearn-primary);
}
@media (min-width: 768px) {
    .sl-feature-hub .sl-hub-wrapper {
        max-width: 800px;
        height: 660px;
    }
    .sl-feature-hub .sl-orbit-track {
        border: 2px dashed var(--smartlearn-card-border);
        pointer-events: none;
    }
    .sl-feature-hub .sl-track-1 {
        width: 400px;
        height: 400px;
        opacity: 0.5;
    }
    .sl-feature-hub .sl-track-2 {
        width: 650px;
        height: 650px;
        opacity: 0.3;
    }
    .sl-feature-hub .sl-hub-center {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 200px;
        height: 200px;
        z-index: 2;
    }
    .sl-feature-hub .sl-orbiting-nodes {
        position: absolute;
        inset: 0;
        z-index: 3;
    }
    .sl-feature-hub .sl-node {
        position: absolute;
        top: 50%;
        left: 50%;
        translate: -50% -50%;
    }
    .sl-feature-hub .sl-node:hover,
    .sl-feature-hub .sl-node:focus-within {
        z-index: 10;
    }
    @keyframes sl-hub-orbit-inner {
        0% { transform: rotate(0deg) translateX(200px) rotate(0deg); }
        100% { transform: rotate(360deg) translateX(200px) rotate(-360deg); }
    }
    @keyframes sl-hub-orbit-outer {
        0% { transform: rotate(0deg) translateX(325px) rotate(0deg); }
        100% { transform: rotate(-360deg) translateX(325px) rotate(360deg); }
    }
    @media (prefers-reduced-motion: no-preference) {
        .sl-feature-hub .sl-node-inner {
            animation: sl-hub-orbit-inner 25s linear infinite;
        }
        .sl-feature-hub .sl-node-outer {
            animation: sl-hub-orbit-outer 35s linear infinite;
        }
        .sl-feature-hub .sl-orbiting-nodes:hover .sl-node,
        .sl-feature-hub .sl-orbiting-nodes:focus-within .sl-node {
            animation-play-state: paused;
        }
    }
    @media (prefers-reduced-motion: reduce) {
        .sl-feature-hub .sl-node-1 { transform: rotate(0deg) translateX(200px) rotate(0deg); }
        .sl-feature-hub .sl-node-2 { transform: rotate(180deg) translateX(200px) rotate(-180deg); }
        .sl-feature-hub .sl-node-3 { transform: rotate(90deg) translateX(325px) rotate(-90deg); }
        .sl-feature-hub .sl-node-4 { transform: rotate(270deg) translateX(325px) rotate(-270deg); }
    }
}
@media (max-width: 767.98px) {
    .sl-feature-hub .sl-hub-wrapper {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 1.5rem;
    }
    .sl-feature-hub .sl-hub-center {
        width: 170px;
        height: 170px;
    }
    .sl-feature-hub .sl-orbiting-nodes {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 0.75rem;
        width: 100%;
    }
    .sl-feature-hub .sl-node-pill {
        justify-content: center;
    }
}
